TieredPolicy:
export interface TieredPolicy {
  review?: "mail-v1";
  repositoryFloor: RiskTier;
  highPeerFloor: number;
  principalDelegated: boolean;
  rules: { path: string; tier: RiskTier; statuses: ("A" | "M" | "D" | "T")[] }[];
}

TieredAcceptance:
export interface TieredAcceptance {
  requested: RiskTier; effective: RiskTier; policyDigest: string; authorityDigest: string;
  reasons: string[]; approvers: string[]; objections: string[];
  principalDecision: string | null; activeFloors: string[];
  snapshot: TierSnapshot; policy: IntegrationPolicyEvidence;
}

ChallengeFloor:
export interface ChallengeFloor {
  readonly finding: string; readonly minimum: "MEDIUM" | "HIGH"; readonly scope: string;
}

ScopeAssessment:
export interface ScopeAssessment {
  readonly finding: string; readonly identity: ExactCandidateIdentity;
  readonly applies: boolean; readonly attestation: string;
}

TierSnapshot:
export interface TierSnapshot {
  readonly identity: ExactCandidateIdentity; readonly requester: string; readonly requested: RiskTier;
  readonly deterministic: { readonly tier: RiskTier; readonly reasons: readonly string[] };
  readonly repositoryFloor: RiskTier;
  readonly floors: readonly ChallengeFloor[] | null;
  readonly scopeAssessments: readonly ScopeAssessment[] | null;
  readonly submitters: readonly string[] | null;
  readonly eligibleResidents: readonly string[] | null;
  readonly reviews: readonly TieredReviewFact[] | null;
  readonly highPeerFloor: number; readonly principalDelegated: boolean;
}

IntegrationCheckSnapshot:
export interface IntegrationCheckSnapshot {
  readonly id: string; readonly argv: readonly string[];
  readonly env: Readonly<Record<string, string>>; readonly timeoutSeconds: number;
  readonly tmpBytes?: number; readonly resources?: Readonly<ResourceLimits>;
}

IntegrationPolicyEvidence:
export interface IntegrationPolicyEvidence {
  readonly tiered: Readonly<TieredPolicy>; readonly protectedPaths: readonly string[];
  readonly checks: readonly IntegrationCheckSnapshot[];
}

TieredReviewFact:
export interface TieredReviewFact {
  readonly id: string; readonly sequence: number; readonly actor: string;
  readonly identity: ExactCandidateIdentity;
  readonly value: "APPROVE" | "OBJECT" | PrincipalDecision;
  readonly revoked: boolean;
}

LegacyAttestationInput:
export type LegacyAttestationInput =
  | { kind: "peer"; identity: ExactCandidateIdentity; verdict: "APPROVE" | "OBJECT"; evidence: string }
  | { kind: "decision"; identity: ExactCandidateIdentity; verdict: "ACCEPT" | "REQUEST_REVISION" | "REJECT"; evidence: string }
  | { kind: "revoke"; attestation: OperationId; evidence: string }
  | { kind: "challenge"; integration: OperationId; identity: ExactCandidateIdentity; evidence: string }
  | { kind: "finding"; challenge: OperationId; valid: boolean; floor: "MEDIUM" | "HIGH" | null; scope: string; evidence: string }
  | { kind: "scope"; finding: OperationId; identity: ExactCandidateIdentity; applies: boolean; evidence: string };

ReviewInput:
export type ReviewInput =
  | { kind: "merge.open"; tier: RiskTier; title: string; reason: string; candidate: Oid; base: Oid }
  | { kind: "challenge.open"; merge: string; tier: "LOW" | "HIGH"; title: string; reason: string; candidate?: Oid; base?: Oid }
  | { kind: "review"; name: string; body: string }
  | { kind: "vote"; name: string; verdict: "approve" | "reject"; body: string; approval?: MessageId }
  | { kind: "cancel"; name: string; reason: string };

ReviewFact:
export type ReviewFact =
  | { kind: "merge.open"; version: 1; name: string; title: string; reason: string; tier: RiskTier;
      identity: ExactCandidateIdentity; submitters: Actor[] }
  | { kind: "challenge.open"; version: 1; name: string; title: string; reason: string; tier: "LOW" | "HIGH";
      identity: ExactCandidateIdentity; submitters: Actor[]; prepared: boolean;
      target: { name: string; request: OperationId; integration: OperationId; identity: ExactCandidateIdentity; tier: RiskTier } }
  | { kind: "review"; version: 1; request: OperationId; body: string }
  | { kind: "vote"; version: 1; request: OperationId; verdict: "approve" | "reject"; body: string; approval: MessageId | null }
  | { kind: "cancel"; version: 1; request: OperationId; reason: string }
  | { kind: "refresh"; version: 1; request: OperationId; main: Oid | null };

ReviewMailMeta:
export type ReviewMailMeta =
  | { role: "thread"; request: OperationId; name: string; revision: number }
  | { role: "approval"; request: OperationId; name: string; votes: OperationId[] }
  | { role: "withdrawn"; request: OperationId; name: string; approval: MessageId }
  | { role: "decision"; request: OperationId; name: string; approval: MessageId }
  | { role: "notice"; request: OperationId; name: string; part: number; parts: number; sha256: string; bytes: number };
